('Firocoxibe', 'Previcox', 'Firocoxibe', 'AINE (COX-2 seletivo)', 'Cães', 'Osteoartrite, dor pós-operatória ortopédica e de tecidos moles.', 'Cães: 5 mg/kg VO SID.', 'Gatos, insuficiência renal/hepática, gestantes.', 'Vômito, diarreia, diminuição do apetite.', 'Outros AINEs, corticosteroides.', 'Não se aplica', 5, 5, 'VO', 'SID', NULL),
('Dipirona', 'Dipirona Vet, D-500', 'Dipirona sódica', 'Analgésico/Antipirético', 'Cães, Gatos, Equinos, Bovinos', 'Analgesia, antipirético. Dor leve a moderada, febre.', 'Cães/Gatos: 25 mg/kg VO/IV/IM BID-TID. Equinos: 20-25 mg/kg IV.', 'Hipersensibilidade, discrasias sanguíneas.', 'Hipotensão (IV rápida), agranulocitose (raro), reações alérgicas.', 'AINEs (risco aditivo GI).', 'Bovinos leite: 4 dias. Carne: 14 dias.', 25, 25, 'VO, IV, IM', 'BID a TID', 500),
