('Metronidazol', 'Flagyl Vet', 'Metronidazol', 'Antibiótico/Antiprotozoário', 'Cães, Gatos', 'Giardíase, infecções anaeróbias, doença inflamatória intestinal, colite.', 'Cães: 15-25 mg/kg VO BID. Gatos: 10-15 mg/kg VO BID. Por 5-7 dias.', 'Gestação, hepatopatia grave, neutropenia.', 'Neurotoxicidade (doses altas), vômito, anorexia, hepatotoxicidade.', 'Fenobarbital, warfarina, cimetidina.', 'Não se aplica', 10, 25, 'VO, IV', 'BID', 40),
('Doxiciclina', 'Doxitrat, Ronaxan', 'Doxiciclina', 'Antibiótico (Tetraciclina)', 'Cães, Gatos', 'Erliquiose, anaplasmose, hemoplasmose, leptospirose, infecções respiratórias.', 'Cães/Gatos: 5-10 mg/kg VO BID por 14-28 dias (hemoparasitas).', 'Gestação, filhotes <6 meses (manchas dentárias).', 'Vômito, esofagite (gatos), fotossensibilização.', 'Antiácidos, ferro, cálcio (reduzem absorção), fenobarbital.', 'Não se aplica', 5, 10, 'VO', 'BID', 20),
('Azitromicina', 'Zitromax Vet', 'Azitromicina', 'Antibiótico (Macrolídeo)', 'Cães, Gatos', 'Infecções respiratórias, cutâneas, bartonella, criptosporidiose.', 'Cães/Gatos: 5-10 mg/kg VO SID por 3-5 dias ou em dias alternados.', 'Hepatopatia grave.', 'Vômito, diarreia, anorexia.', 'Antiácidos, ciclosporina, digoxina.', 'Não se aplica', 5, 10, 'VO', 'SID', 40),
